import copy


def unique_objects(items):
    seen = set()
    result = []
    for item in items:
        if id(item) not in seen:
            seen.add(id(item))
            result.append(item)
    return result


def with_item(order, item):
    new = copy.deepcopy(order)
    new["items"].append(item)
    return new


def freeze(data):
    if isinstance(data, dict):
        return tuple((k, freeze(v)) for k, v in sorted(data.items()))
    if isinstance(data, (list, tuple)):
        return tuple(freeze(x) for x in data)
    if isinstance(data, (set, frozenset)):
        return frozenset(freeze(x) for x in data)
    return data

