lessons.solution:
class Command:
    registry = {}

    def __init_subclass__(cls, name, **kwargs):
        super().__init_subclass__(**kwargs)
        if not callable(getattr(cls, "run", None)):
            raise TypeError(f"{cls.__name__} needs a run method")
        if name in Command.registry:
            raise TypeError(f"command {name!r} already exists")
        Command.registry[name] = cls


def dispatch(name):
    command = Command.registry[name]
    return command().run()

checks.code:
class Hello(Command, name="hello"):
    def run(self):
        return "hi"
assert Command.registry.get("hello") is Hello, Command.registry

class Add(Command, name="add"):
    def run(self):
        return 2 + 2
assert dispatch("add") == 4, dispatch("add")

raised = False
try:
    dispatch("no-such-command")
except KeyError:
    raised = True
assert raised, "dispatch of an unknown name should raise KeyError"

raised = False
try:
    class Broken(Command, name="broken"):
        pass
except TypeError:
    raised = True
assert raised, "a command without run should raise TypeError"
assert "broken" not in Command.registry, sorted(Command.registry)

class First(Command, name="dup"):
    def run(self):
        return 1
raised = False
try:
    class Second(Command, name="dup"):
        def run(self):
            return 2
except TypeError:
    raised = True
assert raised, "a second command named 'dup' should raise TypeError"
assert Command.registry["dup"] is First, Command.registry["dup"]

