cause = "no ConfigError"
try:
    load_port({})
except ConfigError as e:
    cause = e.__cause__
assert isinstance(cause, KeyError), repr(cause)

cause = "no ConfigError"
try:
    load_port({"port": "http"})
except ConfigError as e:
    cause = e.__cause__
assert isinstance(cause, ValueError), repr(cause)

got = "no ExceptionGroup"
try:
    validate({"age": -1})
except ExceptionGroup as eg:
    got = sorted(type(e).__name__ for e in eg.exceptions)
assert got == ["KeyError", "ValueError"], got

got = "no ExceptionGroup"
try:
    validate({"name": "Ada", "age": "36"})
except ExceptionGroup as eg:
    got = [repr(e) for e in eg.exceptions]
assert got == ["ValueError('age')"], got

