lessons.solution:
from functools import wraps


def count_calls(fn):
    @wraps(fn)
    def wrapper(*args, **kwargs):
        wrapper.calls += 1
        return fn(*args, **kwargs)
    wrapper.calls = 0
    return wrapper


def retry(times):
    def decorator(fn):
        @wraps(fn)
        def wrapper(*args, **kwargs):
            for attempt in range(times):
                try:
                    return fn(*args, **kwargs)
                except Exception:
                    if attempt == times - 1:
                        raise
        return wrapper
    return decorator

checks.code:
@count_calls
def first(): pass
@retry(2)
def second(): pass
assert first.__name__ == "first", first.__name__
assert second.__name__ == "second", second.__name__

@count_calls
def a(): pass
@count_calls
def b(): pass
a()
assert b.calls == 0, b.calls

attempts = []
@retry(3)
def flaky(x):
    attempts.append(x)
    if len(attempts) < 3:
        raise ValueError("not yet")
    return x * 2
assert flaky(4) == 8, "should return the first success"
assert attempts == [4, 4, 4], attempts

attempts = []
@retry(2)
def broken():
    attempts.append(1)
    raise KeyError("always")
raised = False
try:
    broken()
except KeyError:
    raised = True
assert raised, "the last exception should be re-raised"
assert len(attempts) == 2, attempts

