lessons.solution:
import operator
from functools import lru_cache, partial, reduce, singledispatch

parse_binary = partial(int, base=2)


def product(nums):
    return reduce(operator.mul, nums, 1)


@lru_cache(maxsize=None)
def grid_paths(rows, cols):
    if rows == 1 or cols == 1:
        return 1
    return grid_paths(rows - 1, cols) + grid_paths(rows, cols - 1)


@singledispatch
def describe(value):
    return "other"


@describe.register
def describe_int(value: int):
    return f"int {value}"


@describe.register
def describe_str(value: str):
    return f"text {value!r}"

